import { Box, Button, Card, CardContent, Container, Stack, Typography } from "@mui/material";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeCourses } from "../types/home";

const BLUE = "#759ae1";
const NAVY = "#17224d";

export default function BestCourses({ data }: { data?: HomeCourses | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 10 }, backgroundColor: "rgba(117, 154, 225, 0.12)" }}>
      <Container maxWidth="lg">
        <Typography sx={{ color: NAVY, fontSize: { xs: 26, md: 36 }, fontWeight: 600, mb: 1 }}>
          {data.highlight ? (
            <>
              <Box component="span" sx={{ color: BLUE }}>
                ---{data.highlight}
              </Box>{" "}
              {data.title}
            </>
          ) : (
            <>
              {data.title ? (
                <>
                  <Box component="span" sx={{ color: BLUE }}>
                    ---
                  </Box>
                  {data.title}
                </>
              ) : null}
            </>
          )}
        </Typography>
        <BlocksText content={data.description} sx={{ color: "#5a6473", mb: 5 }} />
        <Stack
          direction="row"
          flexWrap="wrap"
          useFlexGap
          sx={{ gap: { xs: 2.5, md: 3.5 } }}
          justifyContent="center"
        >
          {(data.items || []).map((course) => (
            <Card
              key={course.id || course.title}
              elevation={0}
              sx={{
                width: { xs: "100%", sm: 320 },
                display: "flex",
                flexDirection: "column",
                border: "1px solid #e6eaf2",
                borderRadius: "16px",
                backgroundColor: "#fff",
                overflow: "hidden",
              }}
            >
              {mediaUrl(course.image) ? (
                <Box
                  component="img"
                  src={mediaUrl(course.image)}
                  alt={course.title}
                  sx={{ width: "100%", height: 177, objectFit: "cover", display: "block" }}
                />
              ) : null}
              <CardContent
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  flex: 1,
                  pt: 2,
                  px: 2.5,
                  pb: 2.5,
                }}
              >
                <Typography sx={{ color: NAVY, fontWeight: 700, fontSize: 20, mb: 1 }}>
                  {course.title}
                </Typography>
                <BlocksText content={course.description} sx={{ color: "#5a6473", mb: 2 }} />
                <Box component="ul" sx={{ pl: 2.5, mb: 2, color: "#5a6473" }}>
                  {(course.features || []).map((item) => (
                    <Typography key={item.id || item.text} component="li" sx={{ mb: 0.5 }}>
                      {item.text}
                    </Typography>
                  ))}
                </Box>
                {course.exploreUrl ? (
                  <Button
                    href={course.exploreUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    endIcon={<ArrowForwardIcon />}
                    sx={{ color: BLUE, px: 0, mt: "auto", alignSelf: "flex-start" }}
                  >
                    Explore Course
                  </Button>
                ) : null}
              </CardContent>
            </Card>
          ))}
        </Stack>
      </Container>
    </Box>
  );
}
